import os                                                   # Імпорт модуля операційної системи для обробки шляхів до файлів
import random                                               # Імпорт стандартного генератора псевдовипадкових чисел
import numpy as np                                          # Підключення бібліотеки чисельних розрахунків та масивів чисел
import pandas as pd                                         # Імпорт бібліотеки для структурованої обробки табличних даних
import matplotlib.pyplot as plt                             # Підключення модуля для створення та збереження графічних ілюстрацій
import requests                                             # Імпорт бібліотеки для надсилання мережевих запитів через протокол
from sklearn.ensemble import IsolationForest                # Імпорт класу алгоритму ізоляційного лісу для виявлення аномалій
from sklearn.metrics import classification_report, confusion_matrix, accuracy_score, precision_score, recall_score, f1_score    # Імпорт функцій розрахунку наукових метрик якості та точності класифікації

def generate_dataset(filepath):                             # Оголошення функції генерації синтетичного датасету показників кімнати
    np.random.seed(42)                                      # Фіксація початкового стану генератора масивів для повторюваності результатів
    random.seed(42)                                         # Фіксація базового стану стандартного випадкового вибору значень
    normal_temp = np.random.uniform(18.0, 30.0, 800)        # Створення масиву з восьмисот нормальних значень кімнатної температури
    normal_hum = np.random.uniform(30.0, 70.0, 800)         # Створення масиву з восьмисот стандартних значень відносної вологості
    normal_light = np.random.randint(50, 801, 800)          # Генерація восьмисот випадкових цілих значень освітленості в нормі
    normal_motion = np.random.choice([0, 1], 800)           # Випадковий розподіл наявності або відсутності людей для норми
    normal_label = ['normal'] * 800                         # Формування списку з восьмисот текстових міток нормального стану
    anom1_temp = np.random.uniform(35.0, 45.0, 15)          # Генерація температурних показників спеки для першого типу аномалії
    anom1_hum = np.random.uniform(80.0, 99.0, 15)           # Створення критичних показників вологості для симуляції аварії пари
    anom1_light = np.random.randint(10, 51, 15)             # Моделювання тьмяного світла в умовах задимлення приміщення
    anom1_motion = np.random.choice([0, 1], 15)             # Випадковий статус фіксації руху під час критичної ситуації
    anom2_temp = np.random.uniform(-5.0, 5.0, 15)           # Генерація мінусових температур для другого типу аномалії замерзання
    anom2_hum = np.random.uniform(20.0, 40.0, 15)           # Моделювання сухого повітря під час аварійного вимкнення опалення
    anom2_light = np.random.randint(0, 1000, 15)            # Довільний рівень освітленості кімнати при вимерзанні приміщення
    anom2_motion = np.random.choice([0, 1], 15)             # Випадковий стан датчика руху в умовах холодного приміщення
    anom3_temp = np.random.uniform(20.0, 25.0, 10)          # Звичайна кімнатна температура під час третього типу аварії
    anom3_hum = np.random.uniform(90.0, 99.0, 10)           # Екстремальна вологість понад дев'яносто відсотків при прориві труби
    anom3_light = np.random.randint(0, 31, 10)              # Темрява на рівні підлоги де стався витік великої води
    anom3_motion = np.zeros(10, dtype=int)                  # Нульовий рух у безлюдному приміщенні під час аварійного затоплення
    anom4_temp = np.random.uniform(15.0, 20.0, 10)          # Прохолодна температура повітря для четвертого типу відхилення
    anom4_hum = np.random.uniform(30.0, 50.0, 10)           # Помірна вологість повітря для сценарію аномального освітлення
    anom4_light = np.random.randint(900, 1101, 10)          # Неприродно яскраве світло понад дев'ятсот люкс у порожній кімнаті
    anom4_motion = np.zeros(10, dtype=int)                  # Відсутність людей при максимальній потужності освітлювальних приладів
    anom_temp = np.concatenate([anom1_temp, anom2_temp, anom3_temp, anom4_temp])                  # Об'єднання всіх згенерованих аномальних температур в один масив
    anom_hum = np.concatenate([anom1_hum, anom2_hum, anom3_hum, anom4_hum])                       # Об'єднання всіх аварійних значень вологості в єдиний список
    anom_light = np.concatenate([anom1_light, anom2_light, anom3_light, anom4_light])             # Злиття всіх аномальних рівнів освітлення в один спільний масив
    anom_motion = np.concatenate([anom1_motion, anom2_motion, anom3_motion, anom4_motion])        # Створення єдиного вектора активності руху для всіх аномалій
    anom_label = ['anomaly'] * 50                                                                 # Створення списку з п'ятдесяти текстових міток аварійного класу
    temp = np.concatenate([normal_temp, anom_temp])                                               # Загальне об'єднання нормальних та аварійних температур у спільний вектор
    hum = np.concatenate([normal_hum, anom_hum])                          # Створення повного масиву всіх значень вологості для датасету
    light = np.concatenate([normal_light, anom_light])                    # Об'єднання всіх вибірок освітленості в один підсумковий стовпець
    motion = np.concatenate([normal_motion, anom_motion])                 # Складання повного масиву станів активності датчика переміщень
    label = normal_label + anom_label                                     # Повне об'єднання списків еталонних міток для оцінки точності
    df = pd.DataFrame({                                                   # Створення двовимірної таблиці даних з іменованими стовпцями ознак
        'temperature': temp,                                              # Запис сформованого масиву температур у відповідний стовпець таблиці
        'humidity': hum,                                                  # Запис значень вологості повітря у відповідну колонку датасету
        'light': light,                                                   # Додавання даних про рівень освітленості приміщення до структури
        'motion': motion,                                                 # Запис стовпця з ознаками наявності або відсутності людей
        'label': label                                                    # Збереження колонки правильних відповідей для подальшого тестування
    })                                                                    # Завершення опису словника структури створюваної таблиці
    df = df.sample(frac=1, random_state=42).reset_index(drop=True)        # Випадкове перемішування рядків таблиці з оновленням порядкових індексів
    df.to_csv(filepath, index=False)                                      # Збереження створеного датасету у файл табличного формату на диск
    return df                                                             # Повернення сформованої та перемішаної таблиці з функції генерації

def train_model(df):                                                      # Оголошення функції навчання моделі виявлення прихованих аномалій
    features = ['temperature', 'humidity', 'light', 'motion']             # Визначення списку ключових вхідних ознак системи для аналізу
    X = df[features]                                                      # Виділення числових стовпців параметрів без використання цільових міток
    model = IsolationForest(contamination=0.06, random_state=42)          # Створення об'єкта моделі ізоляційного лісу з фіксацією відсотка аномалій
    model.fit(X)                                                          # Запуск математичного процесу побудови дерев рішень та навчання моделі
    return model                                                          # Повернення повністю натренованої моделі для подальшого використання

def evaluate_model(model, df):                                                                    # Оголошення процедури оцінки наукових метрик якості навченої моделі
    features = ['temperature', 'humidity', 'light', 'motion']                                     # Формування переліку колонок з числовими параметрами для тесту
    X = df[features]                                                                              # Отримання матриці вхідних показників приміщення для прогнозування
    predictions = model.predict(X)                                                                # Отримання передбачень моделі де одиниця норма а мінус один аномалія
    pred_labels = ['normal' if p == 1 else 'anomaly' for p in predictions]                        # Перетворення числових кодів моделі у зрозумілі текстові мітки
    true_labels = df['label'].values                                                              # Отримання масиву справжніх еталонних міток із початкового датасету
    acc = accuracy_score(true_labels, pred_labels)                                                # Розрахунок метрики загальної частки правильних відповідей системи
    prec = precision_score(true_labels, pred_labels, pos_label='anomaly', zero_division=0)        # Розрахунок точності визначення саме аварійного класу ситуацій
    rec = recall_score(true_labels, pred_labels, pos_label='anomaly', zero_division=0)            # Обчислення повноти виявлення всіх реальних небезпечних аномалій
    f1 = f1_score(true_labels, pred_labels, pos_label='anomaly', zero_division=0)                 # Розрахунок гармонійного середнього значення між точністю та повнотою
    cm = confusion_matrix(true_labels, pred_labels, labels=['normal', 'anomaly'])                 # Побудова квадратної матриці відповідності реальних та передбачених класів
    return acc, prec, rec, f1, cm, pred_labels                                                    # Повернення розрахованих метрик оцінки та списку передбачених відповідей

def test_samples_eval(model, test_samples):                                                       # Функція перевірки моделі на окремих контрольних зразках вимірювань
    features = ['temperature', 'humidity', 'light', 'motion']                                     # Перелік назв параметрів для правильного формування тестової вибірки
    test_df = pd.DataFrame(test_samples, columns=features)                                        # Перетворення списку зразків у структуровану таблицю з колонками
    preds = model.predict(test_df)                                                                # Запуск процесу класифікації нових вимірювань навченою моделлю
    for i, sample in enumerate(test_samples):                                                     # Цикл послідовного перебору кожного перевіреного зразка показників
        pred_label = 'NORMAL' if preds[i] == 1 else 'ANOMALY'                                     # Визначення фінального текстового вердикту на основі коду класифікатора
        t, h, l, m = sample                                                                       # Розпакування окремих значень параметрів вимірювання у змінні
        msg = f"  T={t:<4.1f} H={h:<3} L={l:<3} M={m} --> {pred_label}"                           # Формування базового рядка зі значеннями датчиків та вердиктом
        if pred_label == 'ANOMALY':                                                               # Перевірка чи визначила модель даний стан як небезпечний
            msg += ": Anomalous room state detected!"                                             # Додавання попереджувального тексту до повідомлення про аварію
        print(msg)                                                                                # Виведення сформованого рядка з результатом перевірки в консоль
        
def visualize_results(df, pred_labels, save_path):                                                # Функція побудови та збереження графіків розподілу точок у просторі
    df['prediction'] = pred_labels                                                                # Додавання стовпця з передбаченими мітками до вихідної таблиці даних
    normal_data = df[df['prediction'] == 'normal']                                                # Фільтрація записів які штучний інтелект відніс до норми
    anomaly_data = df[df['prediction'] == 'anomaly']                                              # Вибірка всіх точок які модель розпізнала як аномалії
    fig, axes = plt.subplots(1, 2, figsize=(14, 6))                                               # Створення загального полотна з двома окремими вікнами для графіків
    fig.suptitle("Smart Room Anomaly Detection (Isolation Forest)", fontsize=16)                  # Встановлення головного заголовка для всієї ілюстрації
    axes[0].scatter(normal_data['temperature'], normal_data['humidity'], c='blue', label='Normal', alpha=0.6)           # Нанесення синіх точок нормальних станів на площину температури і вологості
    axes[0].scatter(anomaly_data['temperature'], anomaly_data['humidity'], c='red', label='Anomaly', marker='x')        # Відображення червоних хрестиків аварій на першому графіку
    axes[0].set_title("Temperature vs Humidity - Anomaly Detection")                                                    # Встановлення назви для першого вікна співвідношення параметрів
    axes[0].set_xlabel("Temperature (C)")                                                                               # Підпис горизонтальної осі значень температури у градусах
    axes[0].set_ylabel("Humidity (%)")                                                                                  # Підпис вертикальної осі відносної вологості повітря у відсотках
    axes[0].legend()                                                                                                    # Відображення віконця з поясненням кольорів та позначень точок
    axes[0].grid(True, linestyle='--', alpha=0.5)                                                                       # Увімкнення напівпрозорої координатної сітки для зручності аналізу
    axes[1].scatter(normal_data['temperature'], normal_data['light'], c='blue', label='Normal', alpha=0.6)              # Малювання нормальних точок на площині температури та рівня світла
    axes[1].scatter(anomaly_data['temperature'], anomaly_data['light'], c='red', label='Anomaly', marker='x')           # Нанесення червоних маркерів аномалій на площину другого графіка
    axes[1].set_title("Temperature vs Light - Anomaly Detection")                                                       # Завдання назви для другого вікна порівняння параметрів
    axes[1].set_xlabel("Temperature (C)")                                                                               # Підпис осі значень температури для другого графіка
    axes[1].set_ylabel("Light (lux)")                                                                                   # Підпис вертикальної координати для рівня освітленості кімнати
    axes[1].legend()                                                                                                    # Додавання легенди з розшифровкою маркерів до другого графіка
    axes[1].grid(True, linestyle='--', alpha=0.5)                                                                       # Малювання пунктирної сітки на другому графічному полі
    plt.tight_layout()                                                                                                  # Автоматичне вирівнювання відстаней між елементами зображення
    plt.savefig(save_path)                                                                                              # Збереження готового комбінованого графіка у файл зображення
    plt.close()                                                                                                         # Закриття об'єкта фігури для звільнення оперативної пам'яті
    
def fetch_thingspeak_data(channel_id, api_key="", num_results=100):                                                     # Функція отримання телеметрії з віддаленого хмарного сервера
    url = f"https://api.thingspeak.com/channels/{channel_id}/feeds.json?results={num_results}"                          # Формування адреси мережевого запиту із зазначенням каналу
    if api_key:                                                                                                         # Перевірка чи передано секретний ключ доступу для приватних даних
        url += f"&api_key={api_key}"                                                                                    # Додавання параметра ключа автентифікації до рядка посилання
    try:                                                                                                                # Початок захищеного блоку виконання мережевої операції з обробкою збоїв
        response = requests.get(url, timeout=10)                                                        # Надсилання мережевого запиту з обмеженням часу очікування десять секунд
        response.raise_for_status()                                                                     # Перевірка відсутності помилок передачі та валідності отриманої відповіді
        data = response.json()                                                                          # Перетворення отриманого тексту відповіді у формат структурованого словника
        feeds = data.get('feeds', [])                                                                   # Отримання списку окремих записів вимірювань із загальної структури
        if not feeds:                                                                                   # Перевірка чи список отриманих даних виявився порожнім
            print("No data found in ThingSpeak feed.")                                                  # Виведення повідомлення про відсутність збережених точок у каналі
            return pd.DataFrame()                                                                       # Повернення порожньої таблиці у разі відсутності записів на сервері
        df = pd.DataFrame(feeds)                                                                        # Перетворення отриманого списку записів у таблицю для обробки
        df = df.rename(columns={                                                                        # Перейменування стандартних колонок хмари на зрозумілі імена сенсорів
            'field1': 'temperature',                                                                    # Перейменування першого поля сервера на стовпець температури
            'field2': 'humidity',                                                                       # Заміна назви другого поля на стовпець відносної вологості
            'field3': 'light',                                                                          # Перейменування третього поля на стовпець рівня освітленості
            'field4': 'motion'                                                                          # Заміна імені четвертого поля на зрозумілу назву стовпця руху
        })                                                                                              # Закриття словника правил перейменування полів
        cols_to_keep = ['created_at', 'temperature', 'humidity', 'light', 'motion']                     # Список обов'язкових стовпців які необхідно залишити для аналізу
        existing_cols = [c for c in cols_to_keep if c in df.columns]                                    # Фільтрація списку з урахуванням реально присутніх колонок у відповіді
        df = df[existing_cols]                                                                          # Залишення в таблиці тільки потрібних для роботи інформаційних полів
        for col in ['temperature', 'humidity', 'light', 'motion']:                                      # Цикл послідовного перебору всіх числових колонок датчиків
            if col in df.columns:                                                                       # Перевірка наявності конкретної колонки у структурі отриманої таблиці
                df[col] = pd.to_numeric(df[col], errors='coerce')                                       # Примусове перетворення текстових чисел у дійсні з очищенням помилок
        return df                                                                                       # Повернення очищеної та перетвореної таблиці даних з вимірюваннями
    except Exception as e:                                                                              # Перехоплення будь-яких помилок з'єднання або обробки даних
        print(f"Error fetching data from ThingSpeak: {e}")                                              # Друк тексту помилки що виникла під час виконання запиту
        return pd.DataFrame()                                                                           # Повернення порожньої таблиці у разі виникнення будь-якого збою
if __name__ == "__main__":                                                                              # Точка входу для виконання головного сценарію запуску програми
    print("SMART ROOM - ML ANOMALY DETECTOR")                                                           # Виведення головної назви програми аналізу у вікно терміналу
    data_file = "room_data.csv"                                                                         # Завдання назви файлу для збереження таблиці навчального датасету
    plot_file = "anomaly_plot.png"                                                                      # Визначення назви файлу для збереження згенерованого графіка
    script_dir = os.path.dirname(os.path.abspath(__file__))                                             # Отримання абсолютного шляху до папки де розташовано цей скрипт
    data_filepath = os.path.join(script_dir, data_file)                                                 # Формування повного шляху для збереження таблиці з датасетом
    plot_filepath = os.path.join(script_dir, plot_file)                                                 # Створення точного шляху для збереження фінального зображення
    print("[DATASET] Generating synthetic dataset...")                                                  # Повідомлення користувача про початок генерації навчальної вибірки
    df = generate_dataset(data_filepath)                                                                # Виклик функції створення датасету та збереження його на диск
    num_normal = (df['label'] == 'normal').sum()                                                        # Підрахунок сумарної кількості згенерованих нормальних вибірок
    num_anomaly = (df['label'] == 'anomaly').sum()                                                      # Розрахунок кількості штучно змодельованих аварійних ситуацій
    print(f"[DATASET] Generated {len(df)} samples ({num_normal} normal, {num_anomaly} anomaly)")        # Звіт у консоль про загальну кількість створених прикладів
    print(f"[DATASET] Saved to {data_file}")                                                            # Підтвердження збереження сформованої таблиці у локальний файл
    print()                                                                                             # Друк порожнього рядка для логічного розділення виводу інформації
    print("[MODEL] Training Isolation Forest...")                                                       # Інформування про початок математичного процесу навчання алгоритму
    model = train_model(df)                                                                             # Виклик процедури тренування ізоляційного лісу на згенерованих даних
    print("[MODEL] Training complete.")                                                                 # Повідомлення про успішне завершення побудови аналітичної моделі
    print()                                                                                             # Додавання розділового порожнього рядка у вікні консолі
    acc, prec, rec, f1, cm, pred_labels = evaluate_model(model, df)                                     # Запуск процедури оцінки точності та отримання наукових метрик
    print("[EVAL] Model evaluation:")                                                                   # Заголовок секції виведення результатів математичного тестування
    print(f"  Accuracy:  {acc*100:.1f}%")                                                               # Друк розрахованої загальної точності моделі у відсотковому форматі
    print(f"  Precision: {prec*100:.1f}%")                                                              # Виведення точності виявлення аварій без помилкових тривог
    print(f"  Recall:    {rec*100:.1f}%")                                                               # Друк повноти охоплення системою всіх небезпечних аномалій
    print(f"  F1 Score:  {f1*100:.1f}%")                                                                # Виведення гармонійного середнього значення метрик розпізнавання
    print()                                                                                             # Порожній розділовий рядок перед матрицею плутанини
    print("[EVAL] Confusion Matrix:")                                                                   # Заголовок блоку детального аналізу правильних та хибних спрацювань
    print(f"  True Normal  -> Predicted Normal: {cm[0, 0]:>3} | Predicted Anomaly: {cm[0, 1]:>3}")      # Друк результатів передбачення для реальних нормальних станів
    print(f"  True Anomaly -> Predicted Normal: {cm[1, 0]:>3} | Predicted Anomaly: {cm[1, 1]:>3}")      # Виведення результатів класифікації для справжніх аварійних ситуацій
    print()                                                                                             # Додатковий перехід на новий рядок для структурування
    test_samples = [                                                                                    # Оголошення списку контрольних ситуацій для ручної перевірки моделі
        [24.1, 48, 350, 1],                                                                             # Перший контрольний приклад комфортної кімнати за наявності людини
        [23.8, 49, 340, 1],                                                                             # Другий типовий приклад звичайного житлового мікроклімату в кімнаті
        [39.5, 91, 20, 1],                                                                              # Третій зразок аварії з високою температурою парою та темрявою
        [3.0, 25, 400, 0],                                                                              # Четвертий контрольний зразок критичного падіння температури нижче норми
        [22.0, 95, 10, 0],                                                                              # П'ятий зразок аварійного затоплення водою за звичайної температури
        [28.5, 55, 600, 1],                                                                             # Шостий контрольний зразок теплого літнього дня при яскравому сонці
        [19.0, 40, 200, 0],                                                                             # Сьомий зразок прохолодної спокійної кімнати за відсутності мешканців
        [42.0, 88, 15, 1],                                                                              # Восьмий контрольний зразок критичної спеки з прямою загрозою пожежі
    ]                                                                                                   # Закриття списку тестових багатовимірних векторів показників
    print("[TEST] Testing on new samples:")                                                             # Заголовок секції виведення результатів тестування контрольних зразків
    test_samples_eval(model, test_samples)                                                              # Запуск перевірки моделі на підготовлених контрольних векторах
    print()                                                                                             # Друк порожнього рядка для відокремлення результатів тесту
    visualize_results(df, pred_labels, plot_filepath)                                                   # Виклик функції створення графіків та збереження їх у файл
    print(f"[PLOT] Visualization saved to {plot_file}")                                                 # Повідомлення користувача про успішне збереження файлу малюнка
    print()                                                                                             # Розділовий перехід на наступний рядок у консолі
    channel_id = "3482562"                                                                              # Номер активного публічного каналу користувача на хмарній платформі
    print(f"[THINGSPEAK] Fetching live data from Channel {channel_id}...")                              # Повідомлення про початок завантаження реальних даних з інтернет каналу
    ts_df = fetch_thingspeak_data(channel_id, num_results=10)                                           # Виклик функції отримання десяти останніх записів вимірювань
    if not ts_df.empty:                                                                                 # Перевірка чи вдалося успішно завантажити непорожній список вимірювань
        print(f"[THINGSPEAK] Successfully fetched {len(ts_df)} latest live entries from Wokwi:")        # Звіт про успішне завантаження певної кількості записів
        ts_features = ts_df[['temperature', 'humidity', 'light', 'motion']].fillna(0)                   # Виділення числових колонок із заміною пропусків на нулі
        ts_preds = model.predict(ts_features)                                                           # Прогнозування станів реальних кімнатних вимірювань навченою моделлю
        for i, row in ts_df.reset_index(drop=True).iterrows():                                          # Цикл покрокового виведення вердикту для кожного отриманого запису
            pred_label = 'NORMAL' if ts_preds[i] == 1 else 'ANOMALY'                                    # Визначення текстового результату аналізу для кожного вимірювання
            t = row.get('temperature', 0.0)                                                             # Отримання виміряної температури з поточного рядка таблиці
            h = row.get('humidity', 0.0)                                                                # Зчитування показника відносної вологості з поточного запису
            l = row.get('light', 0)                                                                     # Отримання зафіксованого датчиком рівня освітленості кімнати
            m = int(row.get('motion', 0)) if not pd.isna(row.get('motion')) else 0                      # Отримання статусу активності руху з перевіркою коректності
            created = str(row.get('created_at', ''))[11:19]                                             # Виділення часу надходження вимірювання у форматі годин та хвилин
            msg = f"  [{created}] T={t:<5.1f} H={h:<3.0f} L={l:<3.0f} M={m} --> {pred_label}"           # Формування підсумкового рядка з часом параметрами та вердиктом
            if pred_label == 'ANOMALY':                                                                 # Перевірка чи розпізнав штучний інтелект цей запис як аномальний
                msg += ": Anomalous room state detected!"                                               # Додавання тексту попередження про виявлену небезпечну аномалію
            print(msg)                                                                                  # Друк сформованого звіту по кожному запису хмари в термінал
        print()                                                                                         # Додатковий перехід на новий рядок після завершення списку
    print("Analysis complete.")                                                                         # Підсумкове повідомлення про повне завершення всіх аналітичних операцій